import Phaser from "phaser";
import { GridEngine } from "grid-engine";

import { TestLocation } from "./locations";

export const trappedConfig: Phaser.Types.Core.GameConfig = {
  type: Phaser.AUTO,
  width: 100,
  height: 100,

  physics: {
    default: "arcade",
    arcade: {
      debug: false,
    },
  },
  scene: [TestLocation],
  parent: "game-box",

  title: "Trapped",
  antialias: false,
  pixelArt: true,

  plugins: {
    scene: [
      {
        key: "gridEngine",
        plugin: GridEngine,
        mapping: "gridEngine",
      },

    ],
  },
};
